import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  // Create plane geometry
  const geometry = new THREE.PlaneGeometry(1, 1);

  // Load texture from assets
  const texture = ctx.textureLoader.load(config.assets.imageUrl);

  // Create WebGPU-compatible material
  const material = new MeshBasicNodeMaterial({
    map: texture,
    transparent: true,
  });

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);

  // Apply scene placement
  const [px, py, pz] = config.scenePosition;
  const [rx, ry, rz] = config.sceneRotation;
  const [sx, sy, sz] = config.sceneScale;

  mesh.position.set(px, py, pz);
  mesh.rotation.set(rx, ry, rz);
  mesh.scale.set(sx, sy, sz);

  // Store initial state for animations
  const initialY = py;
  const initialScale = { x: sx, y: sy, z: sz };

  // Initialize handlers
  mesh.userData.handlers = {};

  // Track active timelines
  const activeTimelines = [];

  // Process behavior interactions
  if (config.behavior?.interactions) {
    for (const interaction of config.behavior.interactions) {
      if (interaction.event === 'hover') {
        // Hover lift effect (rise-in preset)
        mesh.userData.handlers.hover = (evt) => {
          activeTimelines.forEach((tl) => tl.kill());
          activeTimelines.length = 0;

          if (evt.type === 'mouseenter') {
            const tl = gsap.to(mesh.position, {
              y: initialY + 0.15,
              duration: 0.7,
              ease: 'power3.out',
            });
            activeTimelines.push(tl);
          } else if (evt.type === 'mouseleave') {
            const tl = gsap.to(mesh.position, {
              y: initialY,
              duration: 0.7,
              ease: 'power3.out',
            });
            activeTimelines.push(tl);
          }
        };
      } else if (interaction.event === 'click') {
        // Click effect: press-down scale + event emission
        mesh.userData.handlers.click = () => {
          activeTimelines.forEach((tl) => tl.kill());
          activeTimelines.length = 0;

          // Press-down animation (scale 0.97 then back)
          const tl = gsap.timeline();
          tl.to(
            mesh.scale,
            {
              x: 0.97,
              y: 0.97,
              z: 0.97,
              duration: 0.12,
              ease: 'back.out',
            },
            0
          );
          tl.to(mesh.scale, {
            x: initialScale.x,
            y: initialScale.y,
            z: initialScale.z,
            duration: 0.2,
            ease: 'back.out',
          });
          activeTimelines.push(tl);

          // Emit navigation event
          if (interaction.effect.startsWith('emit:')) {
            const eventName = interaction.effect.slice(5);
            if (ctx.emit) {
              ctx.emit(eventName);
            }
          }
        };
      }
    }
  }

  // Apply cinematic primitives
  if (config.cinematicPrimitives && Array.isArray(config.cinematicPrimitives)) {
    for (const primitive of config.cinematicPrimitives) {
      if (ctx.primitives?.[primitive.name]) {
        ctx.primitives[primitive.name](mesh, primitive.params || {});
      }
    }
  }

  // Cleanup function
  mesh.userData.cleanup = () => {
    activeTimelines.forEach((tl) => tl.kill());
    activeTimelines.length = 0;
    geometry.dispose();
    material.dispose();
    texture.dispose();
  };

  return mesh;
}
